DROP TABLE IF EXISTS `proposal_departments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `proposal_departments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `编号` bigint DEFAULT NULL,
  `部门名称` text COLLATE utf8mb4_unicode_ci,
  `部门类型` enum('办结','建议处理') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `年份` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `编号` (`编号`),
  CONSTRAINT `proposal_departments_ibfk_1` FOREIGN KEY (`编号`) REFERENCES `proposals` (`编号`)
) ENGINE=InnoDB AUTO_INCREMENT=2549 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
